cd multicode/duckpit/build/par3/l-T/Assets/Game/Code && python3 -I - <<'EOF'
p='Models/SmallModels.cs'
s=open(p,encoding='utf-8').read()
old="""            Color baseC = lucky ? Palette.Lucky : Palette.Duck;
            Color wingC = lucky ? Pal.Mix(Palette.Lucky, Palette.DuckBeak, 0.18f) : Pal.Mix(Palette.Duck, Palette.DuckBeak, 0.14f);
            Color belly = lucky ? Pal.Mix(Palette.Lucky, Palette.DuckBeak, 0.35f) : Pal.Mix(Palette.Duck, Palette.DuckBeak, 0.38f);
            Color gloss = lucky ? Pal.Mix(Palette.LuckyGlow, Palette.White, 0.55f) : Pal.Mix(Palette.Duck, Palette.White, 0.62f);
"""
new="""            // v6l T: тема зала задаёт цвет обычной утки (DuckColor) и долю клюва в крыле (DuckWingMix); null — исходный Palette.Duck, 0,14.
            Color duckCol = DuckColor ?? Palette.Duck;
            Color baseC = lucky ? Palette.Lucky : duckCol;
            Color wingC = lucky ? Pal.Mix(Palette.Lucky, Palette.DuckBeak, 0.18f) : Pal.Mix(duckCol, Palette.DuckBeak, DuckWingMix);
            Color belly = lucky ? Pal.Mix(Palette.Lucky, Palette.DuckBeak, 0.35f) : Pal.Mix(duckCol, Palette.DuckBeak, 0.38f);
            Color gloss = lucky ? Pal.Mix(Palette.LuckyGlow, Palette.White, 0.55f) : Pal.Mix(duckCol, Palette.White, 0.62f);
"""
assert old in s
s=s.replace(old,new)
old2="""        readonly Mesh[] _duckLod = new Mesh[4];
"""
new2="""        readonly Mesh[] _duckLod = new Mesh[4];

        /// v6l T (темы зала): цвет и доля клюва в крыле обычной утки; null — исходный Palette.Duck и 0,14. Золотые (lucky) не зависят.
        public static Color? DuckColor;
        public static float DuckWingMix = 0.14f;

        /// v6l T: перекрасить обычную утку на лету. Геометрия детерминирована — строим утку заново с текущими DuckColor/DuckWingMix
        /// и переносим цвета вершин в уже существующие меши (полная, LOD 1 и 2): все тела, держащие эти меши, меняются сразу.
        /// Возвращает число перекрашенных мешей (0 — меш ещё не строился или число вершин не совпало).
        public int RetintDuck()
        {
            _duckB[0] = null;   // кэш декора (DuckBuilder) пересоберётся с новым цветом
            int n = 0;
            var full = _single[(int)ModelId.Duck];
            if (full)
            {
                var b = new MeshBuilder();
                BuildDuck(b, false, new int[2]);
                n += CopyDuckColors(b, full);
            }
            for (int tier = 1; tier <= 2; tier++)
            {
                var lod = _duckLod[(tier - 1) * 2];
                if (!lod) continue;
                var b = new MeshBuilder();
                BuildDuck(b, false, null, true, tier);
                n += CopyDuckColors(b, lod);
            }
            return n;
        }

        static int CopyDuckColors(MeshBuilder b, Mesh target)
        {
            var tmp = b.ToMesh("DuckRetint", false);
            int ok = 0;
            if (tmp.vertexCount == target.vertexCount)
            {
                var cols = new List<Color>(tmp.vertexCount);
                tmp.GetColors(cols);
                target.SetColors(cols);
                target.UploadMeshData(false);
                ok = 1;
            }
            else Debug.LogWarning($"[PITT] duck retint: vertex count {tmp.vertexCount} != {target.vertexCount} ({target.name})");
            Object.Destroy(tmp);
            return ok;
        }
"""
assert old2 in s
s=s.replace(old2,new2,1)
open(p,'w',encoding='utf-8').write(s)
EOF
grep -n "_single\b" Models/*.cs | head -5

cd multicode/duckpit/build/par3/l-T/Assets/Game/Code && python3 -I - <<'EOF'
p='OnePit/Core/DuckInstancer.cs'
s=open(p,encoding='utf-8').read()
old="""        static readonly Dictionary<Mesh, Mesh[]> _tinted = new Dictionary<Mesh, Mesh[]>(8);
"""
new="""        /// v6l T (темы зала): цвет базовой утки сменился — производные меши (крашеные, золотые, их LOD) пересобираются при следующем
        /// запросе, группы инстансера сбрасываются. Вызывающий затем заново назначает меши телам (HallValue.RefreshLooks).
        public static void InvalidateDerived()
        {
            foreach (var kv in _tinted) { var a = kv.Value; for (int i = 0; i < a.Length; i++) if (a[i]) Object.Destroy(a[i]); }
            foreach (var kv in _gold) if (kv.Value) Object.Destroy(kv.Value);
            _tinted.Clear(); _gold.Clear();
            _lod.Clear(); _lod2.Clear(); _lodReady = false;
            if (_inst) { _inst._groups.Clear(); _inst._list.Clear(); }
        }

        static readonly Dictionary<Mesh, Mesh[]> _tinted = new Dictionary<Mesh, Mesh[]>(8);
"""
assert old in s
s=s.replace(old,new,1)
open(p,'w',encoding='utf-8').write(s)

p='OnePit/Mech/HallValue.cs'
s=open(p,encoding='utf-8').read()
old="""        static Mesh PlainLook(Mesh m) => DuckInstancer.Tinted(m, 2, HallLook.DuckMango, 0.9f);
"""
new="""        /// v6l T: «манго» поверх базовой утки — только тема U; темы B/A/C красят саму базовую утку (SmallModels.DuckColor), v6j — исходная.
        static Mesh PlainLook(Mesh m) => HallTheme.MangoOverlay ? DuckInstancer.Tinted(m, 2, HallLook.DuckMango, 0.9f) : m;

        /// v6l T: смена темы — всем уткам зала заново назначить меш (обычные, крашеные, золотые). Только зал v3 вне sim с инстансером.
        public static int RefreshLooks()
        {
            if (Game.IsSim || !DuckInstancer.On) return 0;
            int n = 0;
            var all = Product.All;
            for (int i = 0; i < all.Count; i++)
            {
                var p = all[i];
                if (!p || p.Kind != ProductKind.Duck || !p.Filter) continue;
                byte bits = _m.TryGetValue(p.Id, out var r) ? r.Bits : (byte)0;
                MeshLook(p, bits);
                n++;
            }
            return n;
        }
"""
assert old in s
s=s.replace(old,new,1)
open(p,'w',encoding='utf-8').write(s)
EOF
